// BenchmarkCreateCommitmentWithTxsSnapshotStack-11    	   20908	     56034 ns/op
func BenchmarkCreateCommitmentWithTxsSnapshotStack(b *testing.B) {
	executor, faucetKey := prepareExecutor(b)
	txs := storageTxs(faucetKey, executor.GetSigner(), 0)
	bundle := &types.Bundle{}
	bundle.SetExecutingTxs(txs)

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		_, err := executor.CreateCommitment(bundle)
		if err != nil {
			b.Fatal(err)
		}
	}
}

// BenchmarkCreateCommitmentWithStateCopy-11               19959	     59578 ns/op
func BenchmarkCreateCommitmentWithStateCopy(b *testing.B) {
	executor, faucetKey := prepareExecutor(b)
	txs := storageTxs(faucetKey, executor.GetSigner(), 0)
	bundle := &types.Bundle{}
	bundle.SetExecutingTxs(txs)
	stateCopy := executor.statedb.Copy()

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		executor.statedb = stateCopy.Copy()
		_, err := executor.CreateCommitment(bundle)
		if err != nil {
			b.Fatal(err)
		}
	}
}

func TestExecutor_CreateCommitment_RevertApplyStateDiff(t *testing.T) {
	t.Parallel()

	const (
		revertStorageChangeHex = "0x0760a5d78b264f1ce5a60b7528ba1c397d48151d22d747eece0732199c4d4a25"
		applyStorageChangeHex  = "0x3d4319c2dabaeaf59cfa278146a48932cf46e5314131871c76f8c35ab02dff65"
	)

	tests := []struct {
		name      string
		revert    bool
		applyDiff bool
		expected  string
	}{
		{
			name:      "Apply transactions changes without reversion",
			revert:    false,
			applyDiff: false,
			expected:  applyStorageChangeHex,
		},
		{
			name:      "Apply storage changes by extracting state diff",
			revert:    true,
			applyDiff: true,
			expected:  applyStorageChangeHex,
		},
		{
			name:      "Revert all transactions changes",
			revert:    true,
			applyDiff: false,
			expected:  revertStorageChangeHex,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			executor, faucetKey := prepareExecutor(t)
			if !tt.revert {
				executor.restorer = state.NoSnapshotTracker
			}

			bundle := &types.Bundle{}
			bundle.SetExecutingTxs(storageTxs(faucetKey, executor.GetSigner(), 0))

			commitment, err := executor.CreateCommitment(bundle)
			if err != nil {
				t.Fatalf("failed to create commitment, err: %s", err)
			}
			if commitment == nil {
				t.Fatal("expected non-empty commitment, got nil")
			}
			if !tt.revert && commitment.StateDiff != nil {
				t.Fatalf("expected empty stateDiff for non-reverted state, got %s", commitment.StateDiff.String())
			}
			if tt.revert && commitment.StateDiff == nil {
				t.Fatal("expected non-empty stateDiff for reverted state, got nil")
			}

			if tt.applyDiff {
				stateDiff, err := rlpEncodeDecode(commitment.StateDiff)
				if err != nil {
					t.Fatal(err)
				}
				err = executor.statedb.AddStateDiff(stateDiff)
				if err != nil {
					t.Fatal(err)
				}
			}

			if hash := executor.statedb.IntermediateRoot(true); hash.String() != tt.expected {
				b := &bytes.Buffer{}
				executor.statedb.IterativeDump(nil, json.NewEncoder(b))
				t.Fatalf("want hash %s, got %s, dump \n%s", tt.expected, hash, b.String())
			}
		})
	}
}

