func setCodeTx(faucetKey *ecdsa.PrivateKey, signer types.Signer, initNonce uint64) types.Transactions {
	senderAddress := crypto.PubkeyToAddress(faucetKey.PublicKey)
	contractAddress := crypto.CreateAddress(senderAddress, initNonce)

	// Prepare constructor parameters
	stateVarA := common.LeftPadBytes(big.NewInt(0).Bytes(), 32)
	stateVarB := common.LeftPadBytes(big.NewInt(0).Bytes(), 32)
	selfDestruct := common.LeftPadBytes(big.NewInt(0).Bytes(), 32)

	// Create contract deployment transaction
	createContractTx := types.MustSignNewTx(faucetKey, signer, &types.LegacyTx{
		Nonce:    uint64(initNonce) + 0,
		Value:    big.NewInt(1e18),
		Gas:      5_000_000,
		GasPrice: big.NewInt(params.InitialBaseFee),
		Data:     slices.Concat(common.FromHex(testdata.MockStateByteCodeHex), stateVarA, stateVarB, selfDestruct),
	})

	// Setup delegation account
	delegationKey, _ := crypto.ToECDSA(hexutil.MustDecode("0xdc599867fc513f8f5e2c2c9c489cde5e71362d1d9ec6e693e0de063236ed1240"))
	delegationAddr := crypto.PubkeyToAddress(delegationKey.PublicKey) // 0xDEa37aE77CefF1F350c25E94c52EB4f65FEdf784

	// Create SetCode authorization - delegation account authorizes its code to be set to contractAddress
	auth, _ := types.SignSetCode(delegationKey, types.SetCodeAuthorization{
		ChainID: *uint256.MustFromBig(signer.ChainID()),
		Address: contractAddress, // Contract address that will become the code
		Nonce:   0,
	})

	// Create SetCode transaction - this will set delegationAddr's code to contractAddress's code
	setCodeTx := types.MustSignNewTx(faucetKey, signer, &types.SetCodeTx{
		Nonce:     uint64(initNonce) + 1,
		GasFeeCap: uint256.NewInt(params.InitialBaseFee),
		Gas:       5_000_000,
		To:        delegationAddr,
		Value:     uint256.NewInt(1e18),
		AuthList:  []types.SetCodeAuthorization{auth},
	})

	actionTx := types.MustSignNewTx(faucetKey, signer, &types.LegacyTx{
		Nonce:    uint64(initNonce) + 2,
		GasPrice: big.NewInt(params.InitialBaseFee),
		Gas:      5_000_000,
		To:       &delegationAddr,
		Value:    big.NewInt(0),
		Data:     testdata.NewMockState().PackWriteStateVarB(common.BigToHash(big.NewInt(1234567890))),
	})

	zeroAuth, _ := types.SignSetCode(delegationKey, types.SetCodeAuthorization{
		ChainID: *uint256.MustFromBig(signer.ChainID()),
		Address: common.Address{}, // Contract address that will become the code
		Nonce:   1,
	})

	setZeroCodeTx := types.MustSignNewTx(faucetKey, signer, &types.SetCodeTx{
		Nonce:     uint64(initNonce) + 3,
		GasFeeCap: uint256.NewInt(params.InitialBaseFee),
		Gas:       5_000_000,
		To:        delegationAddr,
		Value:     uint256.NewInt(1e18),
		AuthList:  []types.SetCodeAuthorization{zeroAuth},
	})

	return types.Transactions{createContractTx, setCodeTx, actionTx, setZeroCodeTx}
}

